public class SolutionTest {
    public static void main(String[] args) {
        eq("", Solution.collapseDuplicates(""));
        eq("", Solution.collapseDuplicates(" \t\r\n\f "));
        eq("one", Solution.collapseDuplicates("one"));
        eq("one", Solution.collapseDuplicates("  one one\tone\none  "));
        eq("A a A", Solution.collapseDuplicates("A A a a A"));
        eq("x y x", Solution.collapseDuplicates("x x y y x x"));
        eq("hello, hello hello,", Solution.collapseDuplicates("hello, hello, hello hello,"));
        eq("a! a?", Solution.collapseDuplicates("\ta!\na!\r\na?\f"));
        eq("Case case CASE", Solution.collapseDuplicates("Case Case case case CASE CASE"));
        expect(IllegalArgumentException.class, () -> Solution.collapseDuplicates(null));

        String input = new String("keep keep separate keep");
        eq("keep separate keep", Solution.collapseDuplicates(input));
        eq("keep keep separate keep", input);
    }

    private static void eq(String expected, String actual) {
        if (!expected.equals(actual)) {
            throw new AssertionError("expected '" + expected + "' but got '" + actual + "'");
        }
    }

    private static void expect(Class<? extends Throwable> type, Runnable action) {
        try {
            action.run();
        } catch (Throwable error) {
            if (type.isInstance(error)) return;
            throw new AssertionError("expected " + type.getName() + " but got " + error, error);
        }
        throw new AssertionError("expected " + type.getName());
    }
}

